{"command": "cd /workspace && python3 src/stems.py 0,2,3,7 >/dev/null 2>&1 && python3 - <<'EOF'
import sys; sys.path.insert(0,'/workspace/src')
from measure import load
import numpy as np
row = 3*2500/160/1000
names = {0:'LEAD',2:'ARP',3:'BASS',7:'PAD1'}
for c in [0,2,3,7]:
    x, sr = load(f'/workspace/render/stem_{c}.wav'); m = x.mean(axis=1)
    d = np.abs(np.diff(m))
    # boundaries: every row (note starts/ends happen on row boundaries); take the first 2 ms after each row start
    rows_idx = [int(round(r*row*sr)) for r in range(0, len(m)//int(row*sr))]
    # ratio of max step within 1 ms after row start to the median step in the same stem
    med = np.median(d[d>0])
    peaks = []
    for i in rows_idx[1:]:
        seg = d[i:i+int(0.001*sr)]
        if len(seg): peaks.append(seg.max())
    peaks = np.array(peaks)
    print('%-5s median step %.5f | p50 %.4f p90 %.4f max %.4f | rows with step>0.2: %d / %d' % (names[c], med, np.median(peaks), np.percentile(peaks,90), peaks.max(), int((peaks>0.2).sum()), len(peaks)))
EOF"}

